#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublasLt.h>
#include <ATen/cuda/CUDAContext.h>
#include <mutex>

struct CublasLtState {
    cublasLtHandle_t handle = nullptr;
    cublasLtMatmulDesc_t matmul_desc = nullptr;
    cublasLtMatrixLayout_t layout_A = nullptr;
    cublasLtMatrixLayout_t layout_B = nullptr;
    cublasLtMatrixLayout_t layout_C = nullptr;
    cublasLtMatmulHeuristicResult_t heuristic_result;
    void* workspace = nullptr;
    size_t workspace_size = 32 * 1024 * 1024; // 32 MB workspace
    bool initialized = false;
    int cached_M = -1, cached_N = -1, cached_K = -1;
};

static CublasLtState g_state;
static std::mutex g_mutex;

static void init_cublaslt_state(int M, int N, int K) {
    if (g_state.initialized && g_state.cached_M == M && g_state.cached_N == N && g_state.cached_K == K) {
        return;
    }

    // Cleanup old descriptors if reinitializing
    if (g_state.layout_A) { cublasLtMatrixLayoutDestroy(g_state.layout_A); g_state.layout_A = nullptr; }
    if (g_state.layout_B) { cublasLtMatrixLayoutDestroy(g_state.layout_B); g_state.layout_B = nullptr; }
    if (g_state.layout_C) { cublasLtMatrixLayoutDestroy(g_state.layout_C); g_state.layout_C = nullptr; }
    if (g_state.matmul_desc) { cublasLtMatmulDescDestroy(g_state.matmul_desc); g_state.matmul_desc = nullptr; }

    if (!g_state.handle) {
        TORCH_CHECK(cublasLtCreate(&g_state.handle) == CUBLAS_STATUS_SUCCESS, "cublasLtCreate failed");
    }

    if (!g_state.workspace) {
        cudaMalloc(&g_state.workspace, g_state.workspace_size);
    }

    // Create matmul descriptor with TF32 fast compute
    cublasComputeType_t compute_type = CUBLAS_COMPUTE_32F_FAST_TF32;
    TORCH_CHECK(cublasLtMatmulDescCreate(&g_state.matmul_desc, compute_type, CUDA_R_32F) == CUBLAS_STATUS_SUCCESS,
                "cublasLtMatmulDescCreate failed");

    // Row-major A (M x K): treat as column-major A^T (K x M) with leading dim K
    // Row-major B (K x N): treat as column-major B^T (N x K) with leading dim N
    // Row-major C (M x N): treat as column-major C^T (N x M) with leading dim N
    // We want C = A * B, in col-major: C^T = B^T * A^T
    // So: op(A_col) = B^T, op(B_col) = A^T => CUBLAS_OP_T for both
    // Actually simpler: pass B as first arg, A as second, both CUBLAS_OP_N
    // cublasLt col-major: C(N,M) = B(N,K) * A(K,M) with OP_N, OP_N
    // This gives C^T = B^T * A^T in row-major, i.e., C = A * B. Correct.

    cublasOperation_t op_N = CUBLAS_OP_N;
    TORCH_CHECK(cublasLtMatmulDescSetAttribute(g_state.matmul_desc, CUBLASLT_MATMUL_DESC_TRANSA,
                &op_N, sizeof(op_N)) == CUBLAS_STATUS_SUCCESS, "set TRANSA failed");
    TORCH_CHECK(cublasLtMatmulDescSetAttribute(g_state.matmul_desc, CUBLASLT_MATMUL_DESC_TRANSB,
                &op_N, sizeof(op_N)) == CUBLAS_STATUS_SUCCESS, "set TRANSB failed");

    // Layout for B as col-major (N x K), leading dim N
    TORCH_CHECK(cublasLtMatrixLayoutCreate(&g_state.layout_A, CUDA_R_32F, N, K, N) == CUBLAS_STATUS_SUCCESS,
                "layout_A (B matrix) create failed");
    // Layout for A as col-major (K x M), leading dim K
    TORCH_CHECK(cublasLtMatrixLayoutCreate(&g_state.layout_B, CUDA_R_32F, K, M, K) == CUBLAS_STATUS_SUCCESS,
                "layout_B (A matrix) create failed");
    // Layout for C as col-major (N x M), leading dim N
    TORCH_CHECK(cublasLtMatrixLayoutCreate(&g_state.layout_C, CUDA_R_32F, N, M, N) == CUBLAS_STATUS_SUCCESS,
                "layout_C create failed");

    // Get heuristic algorithm
    cublasLtMatmulPreference_t preference;
    TORCH_CHECK(cublasLtMatmulPreferenceCreate(&preference) == CUBLAS_STATUS_SUCCESS,
                "cublasLtMatmulPreferenceCreate failed");
    TORCH_CHECK(cublasLtMatmulPreferenceSetAttribute(preference, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                &g_state.workspace_size, sizeof(g_state.workspace_size)) == CUBLAS_STATUS_SUCCESS,
                "set workspace pref failed");

    int returned_results = 0;
    cublasStatus_t heur_status = cublasLtMatmulAlgoGetHeuristic(
        g_state.handle, g_state.matmul_desc,
        g_state.layout_A, g_state.layout_B, g_state.layout_C, g_state.layout_C,
        preference, 1, &g_state.heuristic_result, &returned_results);

    cublasLtMatmulPreferenceDestroy(preference);

    TORCH_CHECK(heur_status == CUBLAS_STATUS_SUCCESS && returned_results > 0,
                "cublasLtMatmulAlgoGetHeuristic failed or no algorithms found");

    g_state.cached_M = M;
    g_state.cached_N = N;
    g_state.cached_K = K;
    g_state.initialized = true;
}

