        C.data_ptr<float>(),
        g_state.layout_C,
        C.data_ptr<float>(),
        g_state.layout_C,
        &g_state.heuristic_result.algo,
        g_state.workspace,
        g_state.workspace_size,
        at::cuda::getCurrentCUDAStream()
    );

    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasLtMatmul failed with status ", (int)status);

    return C;
}
